def deepest_leaves_lca(root):
 def visit(node):
  if node is None:return 0,None
  ld,left=visit(node.left);rd,right=visit(node.right)
  return (ld+1,left) if ld>rd else (rd+1,right) if rd>ld else (ld+1,node)
 return visit(root)[1]

